const root=document.querySelector('#manage-root'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={hotels:[],hotel:null,records:[],entityId:'hotel',busy:false,message:'',error:'',dirty:false},buffers=new Map();
const labels={'save-draft':'保存草稿','publish':'发布','pause':'暂停展示','resume':'恢复展示','discard-draft':'取消草稿'};
async function api(url,data){const r=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw new Error(result.error||'读取失败');return result;}
const record=()=>state.records.find(x=>x.entityId===state.entityId);
const key=()=>state.hotel.id+':'+state.entityId;
function formDraft(){const form=document.querySelector('#content-form');return form?Object.fromEntries(new FormData(form)):null;}
function remember(){const d=formDraft();if(d&&state.dirty)buffers.set(key(),d);}
function values(r){return buffers.get(key())||r.draft||r.published||{intro:r.base.intro||'',story:r.base.story||'',location:r.base.location||'',fee:r.base.fee||'',booking:r.base.booking||'',sourceUrl:r.base.source||'',checkedAt:r.base.checkedAt||'',validUntil:'',evidenceText:r.base.sourceEvidence||'',hoursMode:'keep',hoursText:''};}
async function load(hotelId){state.busy=true;state.error='';try{const data=await api('/api/content?hotelId='+encodeURIComponent(hotelId));state.hotel=data.hotel;state.records=data.records;state.entityId=state.records.some(x=>x.entityId===state.entityId)?state.entityId:'hotel';state.dirty=buffers.has(key());}catch(e){state.error=e.message;}finally{state.busy=false;render();}}
function field(name,label,value,textarea=false){return `<label class="field"><span class="field-label">${label}</span>${textarea?`<textarea name="${name}" rows="${name==='evidenceText'?4:3}" maxlength="4000">${esc(value)}</textarea>`:`<input class="text-input" name="${name}" value="${esc(value)}" maxlength="1200">`}</label>`;}
function render(){if(!state.hotel){root.innerHTML=`<p role="alert">${esc(state.error||'正在读取资料…')}</p>`;return;}const r=record(),v=values(r),deep=state.entityId!=='hotel';
 root.innerHTML=`<div class="manage-intro"><div><span class="product-caption">CONTENT WORKSPACE</span><h1>让每条内容有依据。</h1></div><label class="manage-hotel"><span>酒店</span><select id="manage-hotel">${state.hotels.map(h=>`<option value="${esc(h.id)}" ${h.id===state.hotel.id?'selected':''}>${esc(h.name)} · ${h.tier==='deep'?'深度样例':h.tier==='connected'?'智能体验':'基础资料'}</option>`).join('')}</select></label></div><div class="manage-layout"><aside class="content-sidebar">${state.records.map(x=>`<button data-entity="${esc(x.entityId)}" class="${x.entityId===r.entityId?'active':''}"><strong>${esc(x.entityId==='hotel'?'酒店简介':x.base.name)}</strong><small>${x.presentation==='paused'?'已暂停':x.presentation==='expired'?'已过期':x.verification==='operator-attested'?'人工复核':x.verification==='platform-ai'?'平台AI资料':'来源已关联'}${x.draft?' · 有草稿':''}</small></button>`).join('')}</aside><section class="content-editor"><div class="content-editor-top"><div><span class="tier-badge">${state.hotel.tier==='basic'?'酒店基础资料':state.hotel.tier==='connected'?'自动整理体验资料':'深度体验资料'}</span><h2>${esc(r.entityId==='hotel'?state.hotel.name:r.base.name)}</h2></div><span class="revision">版本 ${r.revision}</span></div><p class="manage-note">${r.published?'当前展示内容已由本机操作人声明核对，仍需关注适用日期。':'当前为已有来源关联资料，尚未逐条人工复核。保存草稿不会改变住客页面。'}</p>${state.message?`<div class="manage-message" role="status">${esc(state.message)}</div>`:''}${state.error?`<div class="error-box" role="alert">${esc(state.error)}</div>`:''}<form id="content-form"><fieldset ${state.busy?'disabled':''}>${field('intro','简介',v.intro,true)}${field('story','详细说明',v.story,true)}${deep?`${field('location','位置',v.location)}${field('fee','费用与权益',v.fee)}${field('booking','参与方式',v.booking)}<label class="field"><span class="field-label">营业时段</span><select name="hoursMode"><option value="keep" ${v.hoursMode==='keep'?'selected':''}>沿用现有资料</option><option value="unknown" ${v.hoursMode==='unknown'?'selected':''}>尚无具体时段</option><option value="set" ${v.hoursMode==='set'?'selected':''}>填写时段</option></select></label>${field('hoursText','填写时段时使用，如 10:00-22:00；多段用分号分隔',v.hoursText)}`:''}${field('sourceUrl','来源链接（HTTPS）',v.sourceUrl)}${v.sourceUrl?`<a class="source-link" href="${esc(v.sourceUrl)}" target="_blank" rel="noreferrer">打开来源，核对原文 ↗</a>`:''}${field('evidenceText','原文依据：贴出支持本条内容的相关原文',v.evidenceText,true)}<div class="form-row"><label class="field"><span class="field-label">核对日期</span><input type="date" name="checkedAt" value="${esc(v.checkedAt)}"></label><label class="field"><span class="field-label">适用截止日期</span><input type="date" name="validUntil" value="${esc(v.validUntil)}"></label></div><p class="note">包含营业时段的资料，发布时需要适用截止日期。核对日期与访问来源不等于酒店实时营业确认。</p><div class="manage-actions"><button class="primary" type="submit">保存草稿</button><button class="secondary" type="button" data-action="discard-draft" ${!r.draft?'disabled':''}>取消草稿</button><span id="dirty-state">${state.dirty?'有未保存更改':r.draft?'草稿已保存':'当前展示版本'}</span></div><div class="publish-area"><label class="check"><input type="checkbox" name="attested"><span>我已阅读来源，核对本条说明、时段及适用范围；没有将缺失信息补写成事实。</span></label><button class="primary" type="button" data-action="publish" ${!r.draft||state.dirty?'disabled':''}>发布已核对资料</button><button class="secondary" type="button" data-action="${r.presentation==='paused'?'resume':'pause'}">${r.presentation==='paused'?'恢复展示':'暂停这条内容'}</button></div></fieldset></form><details class="guide-sources"><summary>修改记录</summary>${r.history.length?r.history.map(h=>`<p class="note">版本 ${h.revision} · ${labels[h.action]||esc(h.action)} · ${esc(new Date(h.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</p>`).join(''):'<p class="note">尚无修改记录。</p>'}</details></section></div>`;
}
async function change(action){if(state.busy)return;const r=record(),form=document.querySelector('#content-form'),data=new FormData(form),payload={hotelId:state.hotel.id,entityId:r.entityId,expectedRevision:r.revision,action};if(action==='save-draft')payload.draft=Object.fromEntries(data);if(action==='publish')payload.attested=data.has('attested');state.busy=true;state.error='';state.message='';
 try{const next=await api('/api/content',payload);state.records=state.records.map(x=>x.entityId===next.entityId?next:x);buffers.delete(key());state.dirty=false;state.message=action==='save-draft'?'草稿已保存，住客页面未改变。':action==='publish'?'已发布，住客页面刷新后生效。':action==='pause'?'已暂停，不再进入新推荐与规划。':action==='resume'?'已恢复展示。':'草稿已取消。';}
 catch(e){state.error=e.message;}finally{state.busy=false;render();}
}
root.addEventListener('submit',e=>{if(e.target.id==='content-form'){e.preventDefault();change('save-draft');}});
root.addEventListener('click',e=>{const item=e.target.closest('[data-entity]');if(item&&!state.busy){remember();state.entityId=item.dataset.entity;state.dirty=buffers.has(key());state.error='';state.message='';render();return;}const action=e.target.closest('[data-action]');if(action)change(action.dataset.action);});
root.addEventListener('change',e=>{if(e.target.id==='manage-hotel'){remember();state.message='';load(e.target.value);}});
root.addEventListener('input',e=>{if(e.target.closest('#content-form')&&e.target.name!=='attested'){state.dirty=true;const label=document.querySelector('#dirty-state');if(label)label.textContent='有未保存更改';const publish=document.querySelector('[data-action=publish]');if(publish)publish.disabled=true;}});
try{const result=await api('/api/content/hotels');state.hotels=result.hotels;const id=new URLSearchParams(location.search).get('hotel')||state.hotels[0]?.id;await load(id);}catch(e){root.innerHTML=`<p role="alert">${esc(e.message)}</p>`;}
